pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        uint256 balanceBefore = address(c).balance;

        vm.deal(owner, 1 ether);
        bool ok;
        try c.sendTo(address(0), 1) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;
        // Reference: require(receiver != address(0)) causes revert, so ok == false and balance unchanged.
        // Bug: no revert, so ok == true and balance decreases by 1.
        assertTrue(!ok && balanceAfter == balanceBefore);
    }
}

