    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;
        try c.sendTo(address(0), 1) {
            // No revert occurred - we should have failed but bug may succeed
        } catch {
            // Revert occurred - expected for reference
        }
        uint256 balanceAfter = address(c).balance;
        // Reference reverts: balance unchanged (balanceBefore == balanceAfter).
        // Bug does not revert: balance decreases (balanceBefore != balanceAfter).
        assertTrue(balanceBefore != balanceAfter, "Bug did NOT transfer to zero address");
    }
}

