pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address receiver1 = address(0x5678);
        address receiver2 = address(0x9ABC);

        vm.deal(address(this), 2 wei);

        // nonOwner sends 1 wei to receiver1
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        (bool okNonOwner,) = address(c).call{value: 0}(""); 
        // Actually call sendTo properly:
        vm.prank(nonOwner);
        c.sendTo(receiver1, 1 wei);

        // owner sends 1 wei to receiver2
        vm.prank(address(this));
        c.sendTo{value: 1 wei}(receiver2, 1 wei);

        assertTrue(address(c).balance == 1 wei);
    }
}

